const inputBytes=storage.readRegularBytes(inputPath,{maxBytes:16384});
need(inputBytes.length===7871&&digest(inputBytes)==="fbbb226ec41761f64d41171c6aef3746c60aa9e58b20ad8ee71db49f91604ccd",'exact reviewed supplier manifest required before parsing');
const input=JSON.parse(inputBytes);
const originalHome=process.env.HOME,originalCodexHome=process.env.CODEX_HOME;
