const group=cgroupText.split('\n').find(l=>l.startsWith('0::'))?.slice(3);
const admittedGroup=process.env.NATIVE_WHOLE_JOB_ADMITTED_CGROUP;
const controller=Number(process.env.NATIVE_WHOLE_JOB_CONTROLLER_PID);
need(group&&group===admittedGroup&&controller===process.ppid,'original CDE controller and direct receiver must share admitted domain and PPID');
need((await readFile('/proc/'+controller+'/cgroup','utf8')).split('\n').some(l=>l==='0::'+group),'controller cgroup differs');
const groupPath='/sys/fs/cgroup'+group;
const nativeValue=async name=>(await readFile(join(groupPath,name),'utf8')).trim();
need(await nativeValue('memory.max')==='268435456'&&await nativeValue('memory.swap.max')==='0'&&await nativeValue('pids.max')==='32','actual aggregate memory/swap/tasks differ');
const [quota,period]=(await nativeValue('cpu.max')).split(/\s+/).map(Number);
need(Number.isSafeInteger(quota)&&Number.isSafeInteger(period)&&quota>0&&quota*4===period,'actual CPU25 bound differs');
const canonicalFile=(p,bytes,hash)=>{const b=storage.readRegularBytes(p,{maxBytes:1048576});need(b.length===bytes&&digest(b)===hash,'source bytes differ: '+p);return b;};
need(await realpath(input.paths.consumer)===input.paths.consumer,'original consumer directory redirected');
need(JSON.stringify((await readdir(input.paths.consumer)).sort())===JSON.stringify(input.selection.sourceFiles.map(f=>f.path).sort()),'only exact original four frozen consumer files are admitted');
for(const f of input.selection.sourceFiles)canonicalFile(join(input.paths.consumer,f.path),f.bytes,f.sha256);
const manifest=JSON.parse(storage.readRegularBytes(join(input.paths.consumer,'package.json'),{maxBytes:1048576}));
need(manifest.name===input.selection.name&&manifest.version===input.selection.version&&Object.keys(manifest.dependencies??{}).length===59,'original Generic259 identity/runtime pins differ');
need(manifest.dependencies['@red-cup-engineering/computer-inference-engine']==='0.2.11','original client-library2.11 pin differs');
need(digest(storage.readRegularBytes(join(input.code.root,'package.json'),{maxBytes:1048576}))===input.code.manifestSHA256,'original immutable Code17 manifest differs');
const codeManifest=JSON.parse(storage.readRegularBytes(join(input.code.root,'package.json'),{maxBytes:1048576}));
need(codeManifest.version===input.code.version&&codeManifest.gitHead===input.code.gitHead,'original immutable Code17 identity differs');
need(digest(storage.readRegularBytes(join(input.code.root,'src/source-registry-closure.mjs'),{maxBytes:1048576}))===input.code.sourceRegistryClosureSHA256,'original Code17 source differs');
need(digest(storage.readRegularBytes(input.pnpm.entry,{maxBytes:1048576}))===input.pnpm.entrySHA256,'original raw PNPM entry differs');
const pnpmRoot=dirname(dirname(input.pnpm.entry));
const pnpmManifest=JSON.parse(storage.readRegularBytes(join(pnpmRoot,'package.json'),{maxBytes:1048576}));
need(pnpmManifest.name==='pnpm'&&pnpmManifest.version===input.pnpm.version,'actual PNPM identity differs');
// Exact immutable raw PNPM dist hash is checked by native sha256sum before ANY Node allocation.
// Original Code17 independently rereads and hashes its supplier again inside its native provider receiving.
need((await lstat(join(pnpmRoot,'dist/pnpm.mjs'))).isFile(),'immutable raw PNPM distribution absent');
const reference=JSON.parse(canonicalFile(input.sharedStore.reference.path,input.sharedStore.reference.bytes,input.sharedStore.reference.sha256));
need(reference.packageManager===input.sharedStore.reference.packageManager&&reference.storeDir===input.sharedStore.directory,'immutable operating-consumer store reference differs');
for(const [p,ino] of [[input.sharedStore.base,input.sharedStore.baseInode],[input.sharedStore.directory,input.sharedStore.inode]]){
 storage.receiveOwnedDataDestination(input.ownerDataRoot,p,{label:'existing standing shared store'});
 const stat=await lstat(p);need(stat.isDirectory()&&await realpath(p)===p&&String(stat.dev)===input.sharedStore.device&&String(stat.ino)===ino&&stat.uid===input.sharedStore.uid,'existing original store custody differs');
}
need(String((await lstat(input.paths.consumer)).dev)===input.sharedStore.device,'source and original store devices differ');
console.log(JSON.stringify({phase:'original-supplier-input-and-domain-received',cgroup:group,controllerPid:controller,receiverPid:process.pid,memoryMaxBytes:268435456,memorySwapMaxBytes:0,tasksMax:32,cpuQuotaPercent:25,sourceCommit:input.selection.commit,sourceFiles:4,storeBase:input.sharedStore.base,storeDirectory:input.sharedStore.directory,storeDevice:input.sharedStore.device,storeInode:input.sharedStore.inode,inferenceOrAccountOperation:false}));
await mkdir(input.paths.effect,{mode:0o700});
await writeFile(input.paths.intent,JSON.stringify({kind:'original-generic-frozen-supplier-intent',at:new Date().toISOString(),manifestSHA256:"fbbb226ec41761f64d41171c6aef3746c60aa9e58b20ad8ee71db49f91604ccd",sourceCommit:input.selection.commit,operation:'receiveSourceRegistryConsumers',modelOperation:false,automaticRetry:false})+'\n',{flag:'wx',mode:0o600});
let receipt;
const made=[];
