const domainQuiet=async()=>{const pids=(await nativeValue('cgroup.procs')).split(/\s+/).filter(Boolean).map(Number);return pids.every(pid=>pid===controller||pid===process.pid);};
try{
 for(const p of [input.paths.staging,input.paths.artifactReceipts,input.paths.metadataCache,input.paths.temporary])made.push(await ownedDirectory(p));
 for(const [name,sub] of [['XDG_CACHE_HOME','cache'],['XDG_CONFIG_HOME','config'],['XDG_DATA_HOME','data'],['PNPM_HOME','pnpm-home']]){
  const p=join(input.paths.metadataCache,sub);await ownedDirectory(p);process.env[name]=p;
 }
 process.env.TMPDIR=input.paths.temporary;
 process.env.NODE_OPTIONS='--max-old-space-size=96 --max-semi-space-size=4';
 process.env.NODE_DISABLE_COMPILE_CACHE='1';
 delete process.env.NODE_COMPILE_CACHE;
 process.env.CI='true';process.env.PNPM_MAX_WORKERS='1';
 const {readRegistryPackageVersion,receiveRegistryTarball}=await import(pathToFileURL(join(input.code.root,'src/registry.mjs')));
 const {receiveSourceRegistryConsumers}=await import(pathToFileURL(join(input.code.root,'src/source-registry-closure.mjs')));
 const {assertRootInstalledDependencyPins}=await import(pathToFileURL(join(input.code.root,'src/native-registry-imports.mjs')));
 const generic=await readRegistryPackageVersion(input.clientArtifact.registry,input.selection.name,input.selection.version);
 need(generic.found===true&&generic.reachable===true&&generic.manifest?.dist?.integrity===input.selection.canonicalIntegrity,'canonical Generic259 artifact identity differs');
 const client=await readRegistryPackageVersion(input.clientArtifact.registry,input.clientArtifact.name,input.clientArtifact.version);
 need(client.found===true&&client.reachable===true&&client.manifest?.dist?.integrity===input.clientArtifact.integrity,'original CIEclient2.11 artifact differs from committed lock');
 const transfer=await receiveRegistryTarball({registry:input.clientArtifact.registry,tarball:client.manifest.dist.tarball,integrity:input.clientArtifact.integrity,destination:input.paths.clientArchive,timeoutMs:30000,inactivityTimeoutMs:10000});
 await writeFile(join(input.paths.effect,'client-artifact-transfer.json'),JSON.stringify({name:input.clientArtifact.name,version:input.clientArtifact.version,tarball:client.manifest.dist.tarball,gitHead:client.manifest.gitHead??null,...transfer},null,2)+'\n',{flag:'wx',mode:0o600});
 const arguments_=[input.pnpm.entry,'--prod','--child-concurrency=1','--network-concurrency=1','--store-dir='+input.sharedStore.base,'--cache-dir='+join(input.paths.metadataCache,'pnpm-metadata'),'--userconfig=/dev/null','--globalconfig=/dev/null','--config.enable-global-virtual-store=false','--config.node-linker=isolated','--config.global=false','--config.manage-package-manager-versions=false','--config.update-notifier=false'];
 console.log(JSON.stringify({phase:'original-code17-ordinary-frozen-call',pnpm:process.execPath,pnpmArguments:arguments_,consumer:input.paths.consumer,clientVersion:'0.2.11',nativeInitialFrozen:false,nativeStoreAssembly:false,expectedStore:input.sharedStore.directory}));
 receipt=await receiveSourceRegistryConsumers({consumerPaths:[input.paths.consumer],releases:[{name:input.clientArtifact.name,version:input.clientArtifact.version,...transfer}],artifactReceiving:[{consumer:input.selection.name,name:input.clientArtifact.name,version:input.clientArtifact.version,registry:input.clientArtifact.registry,archive:{path:input.paths.clientArchive,integrity:input.clientArtifact.integrity},limits:input.clientArtifact.limits}],artifactReceiptDirectory:input.paths.artifactReceipts,logDirectory:input.paths.staging,pnpm:process.execPath,pnpmArguments:arguments_,admissionTimeout:60000,installationTimeout:300000});
 await writeFile(join(input.paths.effect,'original-code17-receiving.json'),JSON.stringify(receipt,null,2)+'\n',{flag:'wx',mode:0o600});
 need(receipt.refusals.length===0&&receipt.packages.length===1,'original frozen receiving refused; preserve native outcome, no retry');
 need(receipt.packages[0].artifactReceiving?.length===1&&receipt.packages[0].artifactReceiving.every(x=>x.ok===true),'original CIEclient2.11 installed archive-member receiving required');
 const pins=await assertRootInstalledDependencyPins({root:input.paths.consumer,manifest});
 need(pins.complete===true&&pins.checked===59,'all original direct runtime pins must be received');
 for(const f of input.selection.sourceFiles)canonicalFile(join(input.paths.consumer,f.path),f.bytes,f.sha256);
 const modules=storage.readRegularBytes(join(input.paths.consumer,'node_modules/.modules.yaml'),{maxBytes:1048576});
 need(await domainQuiet(),'ordinary operation returned but extra whole-job processes remain; retain all cache state');
 for(const info of made.filter(x=>x.path===input.paths.metadataCache||x.path===input.paths.temporary)){
  const now=await lstat(info.path);need(now.isDirectory()&&await realpath(info.path)===info.path&&String(now.dev)===info.dev&&String(now.ino)===info.ino,'released private cache root changed custody');
  await rm(info.path,{recursive:true,force:false});
 }
 need(process.env.HOME===originalHome&&process.env.CODEX_HOME===originalCodexHome,'HOME or CODEX_HOME changed');
 const outcome={kind:'original-generic-frozen-supplier-context-receiving',at:new Date().toISOString(),manifestSHA256:"fbbb226ec41761f64d41171c6aef3746c60aa9e58b20ad8ee71db49f91604ccd",sourceCommit:input.selection.commit,nativeCodeReceiving:join(input.paths.effect,'original-code17-receiving.json'),runtimePins:pins,clientArtifactCompared:receipt.packages[0].artifactReceiving?.every(x=>x.ok===true)===true,modulesMetadata:{path:join(input.paths.consumer,'node_modules/.modules.yaml'),bytes:modules.length,sha256:digest(modules),decodedStorePathNotIndependentlyClaimed:true},sharedStorePreserved:true,sharedStoreReference:input.sharedStore.reference,releaseMetadataAndTemporaryRetired:true,homeAndCodexHomePreserved:true,domainQuiescentExceptOriginalControllerAndReceiver:true,fullGenericSourceProduct:false,sourceTransformationPortQualified:false,modelOperation:false,codeGenerated:false,productionChanged:false};
 await writeFile(input.paths.receiving,JSON.stringify(outcome,null,2)+'\n',{flag:'wx',mode:0o600});
 console.log(JSON.stringify({phase:'original-supplier-native-receiving-returned',receiving:input.paths.receiving,pins:pins.checked,clientArtifactCompared:outcome.clientArtifactCompared,releaseMetadataAndTemporaryRetired:true}));
}catch(error){
 let quiet=null;try{quiet=await domainQuiet();}catch{}
 const failure={kind:'original-generic-frozen-supplier-refusal',at:new Date().toISOString(),manifestSHA256:"fbbb226ec41761f64d41171c6aef3746c60aa9e58b20ad8ee71db49f91604ccd",code:typeof error.code==='string'?error.code:null,message:String(error.message).slice(0,2048),originalCodeReceipt:receipt?join(input.paths.effect,'original-code17-receiving.json'):null,domainQuiescentExceptOriginalControllerAndReceiver:quiet,privateCacheAndWorkRetained:true,automaticRetry:false,modelOperation:false,fullGenericSourceProduct:false};
 await writeFile(join(input.paths.effect,'refused.json'),JSON.stringify(failure,null,2)+'\n',{flag:'wx',mode:0o600});
 console.error(JSON.stringify(failure));process.exitCode=1;
